// Screenshot driver: node shoot.mjs <width> <height> <outPath> [url]
// Scrolls through the page first so IntersectionObserver reveals fire.
import { chromium } from 'playwright-core';

const [width, height, out, url = 'http://localhost:8321/'] = [
  Number(process.argv[2]), Number(process.argv[3]), process.argv[4], process.argv[5],
];

const b = await chromium.launch({
  executablePath: '/opt/pw-browsers/chromium-1194/chrome-linux/chrome',
  args: ['--no-sandbox'],
});
const p = await b.newPage({ viewport: { width, height }, deviceScaleFactor: width < 800 ? 2 : 1 });
await p.goto(url, { waitUntil: 'networkidle' });
await p.evaluate(async () => {
  const step = window.innerHeight * 0.7;
  for (let y = 0; y < document.body.scrollHeight; y += step) {
    window.scrollTo(0, y);
    await new Promise(r => setTimeout(r, 350));
  }
  window.scrollTo(0, document.body.scrollHeight);
});
// let the session-terminal typing animation finish
await p.waitForTimeout(7000);
await p.evaluate(() => window.scrollTo(0, 0));
await p.waitForTimeout(400);
await p.screenshot({ path: out, fullPage: true });
await b.close();
console.log('saved', out);

